<script setup>
import {t,setLanguage} from "./i18n.js";
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue';
import Locatiepicker from './Locatiepicker.vue';
const mapOpen=ref(false);
function useMap(r){if(!gesloten.value){Object.assign(editor.value,{StraatHuisnummer:r.StraatHuisnummer,Plaats:r.Plaats,Postcode:r.Postcode,Latitude:r.Latitude,Longitude:r.Longitude,KaartLocatie:true});}mapOpen.value=false;}
function clearMap(){editor.value.KaartLocatie=false;}
import {matchesUnit} from './unit-filter.js';
import {sortAvailableUnits} from './unit-sort.js';
import {version as appVersion} from '../package.json';
import {maakAlarmtekst} from './alarmtekst.js';
import Databasebeheer from './Databasebeheer.vue';
const databaseBeheer=ref(false);
import PolygonenImport from './PolygonenImport.vue';
import Pagerbeheer from './Pagerbeheer.vue';
import Eenhedenbeheer from './Eenhedenbeheer.vue';
import Gebruikersbeheer from './Gebruikersbeheer.vue';
import Systeembeheer from './Systeembeheer.vue';
const systeemBeheer=ref(false);
import Prioriteitenbeheer from './Prioriteitenbeheer.vue';
const prioriteiten=ref([]),prioBeheer=ref(false);
async function laadPrio(){const g=sessionGeneration;try{const r=await api('/prioriteiten');if(g===sessionGeneration)prioriteiten.value=r;}catch{}}
import Statusbeheer from './Statusbeheer.vue';
import Opschalingsbeheer from './Opschalingsbeheer.vue';
const opsBeheer=ref(false),opsOpties=ref({mono:[],multi:[]});
async function laadOps(){const g=sessionGeneration;try{const r=await api('/opschalingsniveaus');if(g===sessionGeneration)opsOpties.value=r;}catch{}}
import Classificatiebeheer from './Classificatiebeheer.vue';
const polygonenBeheer=ref(false);
const pagerBeheer=ref(false),unitBeheer=ref(false),beheer=ref(false),classBeheer=ref(false),classificaties=ref([]);
async function laadClass(){try{classificaties.value=await api('/classificaties');}catch{}}
const leeg=()=>({Naam:'',StraatHuisnummer:'',Postcode:'',Plaats:'',Telefoon:'',Classificatie:'',Prioriteit:null,MasterID:null,Status:'Open',OpschalingMono:'',OpschalingMulti:''});
const editor=ref(leeg()),meldingen=ref([]),filter=ref('Open'),zoek=ref(''),fout=ref(''),online=ref(false),bezig=ref(false);
const koppelOpen=ref(false),masterKeuze=ref(null),koppelFout=ref('');
const onopgeslagen=computed(()=>!!editor.value.ID&&(!!editor.value.KaartLocatie||!!logtekst.value.trim()||Object.keys(leeg()).some(k=>editor.value[k]!==basis?.[k])));
function openKoppel(){if(!editor.value.ID||gesloten.value||bezig.value)return;if(onopgeslagen.value){fout.value='Sla eerst de wijzigingen en logtekst op.';return;}masterKeuze.value=null;koppelFout.value='';koppelOpen.value=true;}
async function bevestigKoppel(){if(bezig.value||gesloten.value||!kandidaten.value.some(m=>m.ID===masterKeuze.value))return;bezig.value=true;koppelFout.value='';try{const m=await api(`/meldingen/${editor.value.ID}/koppel`,{method:'POST',body:JSON.stringify({MasterID:masterKeuze.value})});editor.value={...m,Classificatie:m.Classificatie??''};basis={...editor.value};koppelOpen.value=false;await laadLogs();await laad();}catch(e){koppelFout.value=e.message;}finally{bezig.value=false;}}

const unitOpen=ref(false),unitChoices=ref([]),unitSelected=ref([]),linkedUnits=ref([]),unitError=ref('');let unitSeq=0;
const unitStatusTarget=ref(null),unitStatusValue=ref(null),unitStatusError=ref('');
const statusBeheer=ref(false),statusOptions=ref([]);
const statusNumber=id=>statusOptions.value.find(s=>s.StatusID===id)?.StatusNummer;
async function laadStatus(){const g=sessionGeneration;try{const r=await api('/eenheden/statussen');if(g===sessionGeneration)statusOptions.value=r;}catch{}}
function linkedLabel(u){const details=[u.Omschrijving,u.Locatie].filter(v=>v?.trim()).join(', ');return `${u.TactischeNaam}${details?' ('+details+')':''} - ${u.Status??'Onbekend'}`;}
function openUnitStatus(u){if(bezig.value||!online.value||gesloten.value)return;unitStatusTarget.value={...u,MeldingID:editor.value.ID};unitStatusValue.value=u.StatusID;unitStatusError.value='';}
async function saveUnitStatus(){const u=unitStatusTarget.value;if(!u||bezig.value||gesloten.value||unitStatusValue.value===u.StatusID)return;bezig.value=true;unitStatusError.value='';try{await api(`/meldingen/${u.MeldingID}/eenheden/${u.ID}/status`,{method:'PATCH',body:JSON.stringify({StatusID:unitStatusValue.value,OriginalStatusID:u.StatusID})});unitStatusTarget.value=null;await loadLinked();await laadLogs();await laad();}catch(e){unitStatusError.value=e.message;}finally{bezig.value=false;}}

async function loadLinked(){const id=editor.value.ID,n=++unitSeq;if(!id){linkedUnits.value=[];return;}try{const r=await api(`/meldingen/${id}/eenheden`);if(n===unitSeq&&editor.value.ID===id)linkedUnits.value=r;}catch(e){if(n===unitSeq)unitError.value=e.message;}}
watch(()=>editor.value.ID,()=>{linkedUnits.value=[];unitError.value='';loadLinked();});
const unitOriginal=ref([]),unitLoading=ref(false);
const alarmOpen=ref(false),alarmUnits=ref([]),alarmIDs=ref([]),alarmTekst=ref(''),alarmFout=ref(''),alarmSucces=ref('');
const standaardAlarm= computed(()=>maakAlarmtekst(editor.value,alarmUnits.value,alarmIDs.value));
watch(standaardAlarm,(nieuw,oud)=>{if(alarmOpen.value&&alarmTekst.value===oud)alarmTekst.value=nieuw;});
const kanAlarmeren=computed(()=>alarmOpen.value&&!bezig.value&&!unitLoading.value&&!gesloten.value&&alarmIDs.value.length>0&&alarmTekst.value.trim().length>3);
async function alarmeren(){if(!kanAlarmeren.value)return;alarmFout.value='';alarmSucces.value='';bezig.value=true;try{const result=await api(`/meldingen/${editor.value.ID}/alarmeren`,{method:'POST',body:JSON.stringify({IDs:alarmIDs.value,Tekst:alarmTekst.value.trim()})});alarmOpen.value=false;alarmTekst.value='';if(result.skipped?.length)window.alert('Alarmering verzonden voor eenheden met pagercode. Niet gealarmeerd wegens ontbrekende pagercode: '+result.skipped.join(', '));}catch(e){alarmFout.value=e.message;if(e.code==='PAGER_CODE_MISSING')window.alert(e.message);}finally{bezig.value=false;}}

const unitDirty=computed(()=>unitSelected.value.length!==unitOriginal.value.length||unitSelected.value.some(id=>!unitOriginal.value.includes(id)));
const unitPolygonPriority=ref([]);
const unitFilter=ref('');
function unitsForSide(side){const list=unitChoices.value.filter(u=>unitSelected.value.includes(u.ID)===side);return side?list:sortAvailableUnits(list.map(u=>({...u,StatusNummer:statusNumber(u.StatusID)})),unitPolygonPriority.value).filter(u=>matchesUnit(u,unitFilter.value));}
async function openUnits(){if(!editor.value.ID||gesloten.value||bezig.value)return;unitFilter.value='';unitOpen.value=true;unitLoading.value=true;alarmIDs.value=[];alarmTekst.value="";alarmFout.value="";alarmSucces.value="";unitSelected.value=[];unitOriginal.value=[];unitChoices.value=[];unitError.value='';unitPolygonPriority.value=[];try{const [free,linked,geo]=await Promise.all([api('/eenheden/beschikbaar'),api(`/meldingen/${editor.value.ID}/eenheden`),api(`/meldingen/${editor.value.ID}/polygonen`)]);unitPolygonPriority.value=[geo.PolygoonP1,geo.PolygoonP2,geo.PolygoonP3];unitChoices.value=[...new Map([...free,...linked].map(u=>[u.ID,u])).values()];unitOriginal.value=linked.map(u=>u.ID);unitSelected.value=[...unitOriginal.value];}catch(e){unitError.value=e.message;}finally{unitLoading.value=false;}}
function moveUnit(id){if(bezig.value||unitLoading.value)return;unitSelected.value=unitSelected.value.includes(id)?unitSelected.value.filter(n=>n!==id):[...unitSelected.value,id];}
async function linkUnits(andAlarm=false){if(bezig.value||gesloten.value||unitLoading.value||(!unitDirty.value&&!andAlarm))return;bezig.value=true;unitError.value='';try{await api(`/meldingen/${editor.value.ID}/eenheden`,{method:'POST',body:JSON.stringify({IDs:unitSelected.value,OriginalIDs:unitOriginal.value})});unitOpen.value=false;if(andAlarm){alarmUnits.value=unitChoices.value.filter(u=>unitSelected.value.includes(u.ID));alarmIDs.value=alarmUnits.value.map(u=>u.ID);alarmTekst.value=standaardAlarm.value;alarmFout.value="";alarmSucces.value="";alarmOpen.value=true;}await loadLinked();await laadLogs();await laad();}catch(e){unitError.value=e.message;}finally{bezig.value=false;}}
const kandidaten=computed(()=>meldingen.value.filter(m=>m.ID!==editor.value?.ID&&m.MasterID===null&&m.Status==='Open'));
const logregels=ref([]),logtekst=ref(''),logfout=ref('');let logvolg=0;
async function laadLogs(){const id=editor.value.ID,n=++logvolg;if(!id)return;try{const data=await api(`/meldingen/${id}/logregels`);if(n===logvolg&&editor.value.ID===id){logregels.value=data;logfout.value='';}}catch(e){if(n===logvolg)logfout.value=e.message;}}
function resetLogs(){++logvolg;logregels.value=[];logtekst.value='';logfout.value='';}
let basis=null;
const gesloten=computed(()=>!!editor.value.ID&&(basis?.Status==='Gesloten'||meldingen.value.some(m=>m.ID===editor.value.ID&&m.Status==='Gesloten')));
function bewerk(m){if(bezig.value||unitOpen.value||alarmOpen.value||unitStatusTarget.value)return;resetLogs();editor.value={...m,Classificatie:m.Classificatie??''};basis={...editor.value};fout.value='';laadLogs();window.scrollTo({top:0,behavior:'smooth'});}
function resetEditor(){resetLogs();++unitSeq;linkedUnits.value=[];unitError.value='';editor.value=leeg();basis=null;fout.value='';}
function nieuw(){if(bezig.value||unitOpen.value||alarmOpen.value||unitStatusTarget.value)return;resetEditor();}
let timer,volg=0,sessionGeneration=0;
const verbindingsfout=ref('');
async function api(url,options={}){const g=sessionGeneration;const r=await fetch('/api'+url,{cache:'no-store',...options,headers:{'Content-Type':'application/json',...options.headers}});const data=await r.json();if(r.status===401&&url!=='/login'&&g===sessionGeneration)resetSession();if(!r.ok){const e=Error(data.error||'Serverfout');e.code=data.code;throw e;}return data;}
let lastMeldingID=null,audioContext=null,audioRevision=0;
const audioBusy=ref(false),audioError=ref('');
function unlockAudio(){if(!gebruiker.value)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;audioContext??=new C();if(audioContext.state==='suspended')audioContext.resume().catch(()=>{});}catch{}}
function ping(){if(!audioContext||audioContext.state!=='running')return;try{const t=audioContext.currentTime,o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.setValueAtTime(880,t);g.gain.setValueAtTime(0.001,t);g.gain.exponentialRampToValueAtTime(0.2,t+0.02);g.gain.exponentialRampToValueAtTime(0.001,t+0.4);o.connect(g).connect(audioContext.destination);o.start(t);o.stop(t+0.42);}catch{}}
function checkNewMeldingen(data){const max=data.reduce((n,m)=>Math.max(n,m.ID),0);if(lastMeldingID!==null&&max>lastMeldingID&&gebruiker.value?.Audio===1)ping();lastMeldingID=Math.max(lastMeldingID??0,max);}
async function toggleAudio(){if(!gebruiker.value||audioBusy.value)return;unlockAudio();const g=sessionGeneration;audioBusy.value=true;audioError.value='';++audioRevision;try{const r=await api('/eigen-audio',{method:'PATCH',body:JSON.stringify({Audio:gebruiker.value.Audio===1?0:1})});if(g===sessionGeneration&&gebruiker.value){gebruiker.value={...gebruiker.value,Audio:r.Audio};if(r.Audio===1)ping();}}catch(e){if(g===sessionGeneration)audioError.value=e.message;}finally{if(g===sessionGeneration){audioBusy.value=false;++audioRevision;}}}
async function laad(){if(!gebruiker.value)return;const n=++volg;for(let poging=0;poging<2;poging++){try{const data=await api('/meldingen');if(n===volg&&gebruiker.value){checkNewMeldingen(data);meldingen.value=data;online.value=true;verbindingsfout.value='';}return;}catch(e){if(n!==volg||!gebruiker.value)return;if(poging===0&&e instanceof TypeError){await new Promise(resolve=>setTimeout(resolve,400));if(n!==volg||!gebruiker.value)return;continue;}online.value=false;verbindingsfout.value=e.message;return;}}}
async function actie(fn){bezig.value=true;fout.value='';try{await fn();await laad();}catch(e){fout.value=e.message;}finally{bezig.value=false;}}
const kanHeropenen=computed(()=>gesloten.value&&basis?.Status==='Gesloten'&&editor.value.MasterID===null&&gebruiker.value?.KanHeropenen);
const kanOpslaan=computed(()=>!bezig.value&&online.value&&(!gesloten.value||kanHeropenen.value&&editor.value.Status==='Open')&&(!!editor.value.ID||!!(editor.value.StraatHuisnummer.trim()&&editor.value.Plaats.trim())));
const logveld=ref(null);
async function focusLogregel(){await nextTick();const veld=logveld.value;if(!veld||veld.disabled)return;veld.focus();veld.setSelectionRange(veld.value.length,veld.value.length);}
function logEnter(event){if(event.isComposing||event.keyCode===229||event.shiftKey)return;event.preventDefault();if(!event.repeat&&kanOpslaan.value)opslaan();}
function opslaan(){if(!kanOpslaan.value)return;actie(async()=>{const id=editor.value.ID;const m=await api(id?`/meldingen/${id}`:'/meldingen',{method:id?'PATCH':'POST',body:JSON.stringify({...editor.value,Basis:basis,Logtekst:gesloten.value?'':logtekst.value})});editor.value={...m,Classificatie:m.Classificatie??''};basis={...editor.value};meldingen.value=meldingen.value.map(r=>r.ID===m.ID?m:r);logtekst.value='';if(m.Status==='Gesloten'){resetEditor();return;}await laadLogs();if(!id){if(filter.value!=='Alle')filter.value=m.Status;zoek.value='';}});}

const zichtbaar=computed(()=>meldingen.value.filter(m=>(filter.value==='Alle'||m.Status===filter.value)&&[m.ID,m.MasterID??'',m.Naam,m.StraatHuisnummer,m.Postcode,m.Plaats,m.Telefoon,m.Classificatie,m.Prioriteit,m.OpschalingMono,m.OpschalingMulti,m.EenhedenOverzicht].join(' ').toLowerCase().includes(zoek.value.toLowerCase())));
const appTitle=ref('EMCOM Dispatch');
watch(appTitle,v=>{document.title=v;},{immediate:true});
const gebruiker=ref(null),authReady=ref(false),loginNaam=ref(''),loginWachtwoord=ref(''),loginFout=ref(''),loginBezig=ref(false);
const paletteBusy=ref(false),paletteError=ref('');
let paletteRevision=0;
watch(()=>gebruiker.value?.Kleurpalet,v=>{document.documentElement.dataset.palette=v==='Licht'?'light':'dark';},{immediate:true});
async function togglePalette(){if(!gebruiker.value||paletteBusy.value)return;const g=sessionGeneration;const target=gebruiker.value.Kleurpalet==='Licht'?'Donker':'Licht';paletteBusy.value=true;paletteError.value='';++paletteRevision;try{const result=await api('/eigen-kleurpalet',{method:'PATCH',body:JSON.stringify({Kleurpalet:target})});if(g===sessionGeneration&&gebruiker.value)gebruiker.value={...gebruiker.value,Kleurpalet:result.Kleurpalet};}catch(e){if(g===sessionGeneration)paletteError.value=e.message;}finally{if(g===sessionGeneration){++paletteRevision;paletteBusy.value=false;}}}
function openBeheer(event){const choice=event.target.value;event.target.value='';if(bezig.value||koppelOpen.value||unitOpen.value||alarmOpen.value||unitStatusTarget.value||!gebruiker.value)return;if(['classes','pager','polygonen','database','opschaling','status','prioriteiten','systeem'].includes(choice)&&!gebruiker.value.KanGebruikersBeheren)return;systeemBeheer.value=choice==='systeem';prioBeheer.value=choice==='prioriteiten';statusBeheer.value=choice==='status';opsBeheer.value=choice==='opschaling';databaseBeheer.value=choice==='database';polygonenBeheer.value=choice==='polygonen';pagerBeheer.value=choice==='pager';beheer.value=choice==='users';classBeheer.value=choice==='classes';unitBeheer.value=choice==='units';}
function databaseReset(result){if(result.logout){resetSession();return;}resetEditor();laad();laadClass();laadOps();laadStatus();laadPrio();}
function resetSession(){systeemBeheer.value=false;mapOpen.value=false;lastMeldingID=null;audioBusy.value=false;audioError.value="";++audioRevision;paletteBusy.value=false;paletteError.value='';++paletteRevision;++sessionGeneration;++unitSeq;unitStatusTarget.value=null;fout.value='';verbindingsfout.value='';unitError.value='';alarmOpen.value=false;alarmUnits.value=[];databaseBeheer.value=false;polygonenBeheer.value=false;pagerBeheer.value=false;alarmTekst.value="";alarmIDs.value=[];unitBeheer.value=false;beheer.value=false;classBeheer.value=false;classificaties.value=[];prioBeheer.value=false;statusBeheer.value=false;prioriteiten.value=[];opsBeheer.value=false;opsOpties.value={mono:[],multi:[]};clearInterval(timer);++volg;resetLogs();gebruiker.value=null;meldingen.value=[];editor.value=leeg();basis=null;online.value=false;koppelOpen.value=false;unitOpen.value=false;linkedUnits.value=[];zoek.value='';filter.value='Open';}
watch(()=>gebruiker.value?.KanGebruikersBeheren,v=>{if(!v){systeemBeheer.value=false;prioBeheer.value=false;statusBeheer.value=false;opsBeheer.value=false;classBeheer.value=false;databaseBeheer.value=false;polygonenBeheer.value=false;pagerBeheer.value=false;}});
async function refreshUser(){const g=sessionGeneration,p=paletteRevision,a=audioRevision;try{const u=await api('/session');if(g===sessionGeneration&&gebruiker.value){if(p!==paletteRevision||paletteBusy.value)u.Kleurpalet=gebruiker.value.Kleurpalet;if(a!==audioRevision||audioBusy.value)u.Audio=gebruiker.value.Audio;gebruiker.value=u;setLanguage(u.Taal);appTitle.value=u.Titel||'EMCOM Dispatch';}}catch{}}
function startSession(u){lastMeldingID=null;clearInterval(timer);++sessionGeneration;fout.value='';verbindingsfout.value='';gebruiker.value=u;setLanguage(u.Taal);appTitle.value=u.Titel||'EMCOM Dispatch';laad();laadClass();laadOps();laadStatus();laadPrio();timer=setInterval(()=>{if(!gebruiker.value)return;laad();laadLogs();loadLinked();refreshUser();laadClass();laadOps();laadStatus();laadPrio();},3000);}
async function inloggen(){if(loginBezig.value)return;loginBezig.value=true;loginFout.value='';try{startSession(await api('/login',{method:'POST',body:JSON.stringify({Gebruikersnaam:loginNaam.value,Wachtwoord:loginWachtwoord.value})}));unlockAudio();loginWachtwoord.value='';}catch(e){loginFout.value=e.message;}finally{loginBezig.value=false;}}
async function uitloggen(){try{await api('/logout',{method:'POST'});resetSession();}catch(e){if(gebruiker.value)fout.value=e.message;}}
onMounted(async()=>{window.addEventListener("pointerdown",unlockAudio);window.addEventListener("keydown",unlockAudio);try{const config=await api('/taal');setLanguage(config.Taal);appTitle.value=config.Titel||'EMCOM Dispatch';}catch{}try{startSession(await api('/session'));}catch{}finally{authReady.value=true;}});onUnmounted(()=>{clearInterval(timer);window.removeEventListener("pointerdown",unlockAudio);window.removeEventListener("keydown",unlockAudio);audioContext?.close().catch(()=>{});});
</script>
<template>
<header v-if="gebruiker"><div><small>{{appTitle}}</small><h1>{{gebruiker.Organisatie || 'Meldkamer'}}</h1></div><span :class="online?'live':'offline'">● {{t(online?'Verbonden':'Niet verbonden')}}</span><div class="userbar"><span>{{gebruiker.Voornaam}} {{gebruiker.Achternaam}}</span><select class="beheer-menu" :aria-label="t('Beheer')" :value="''" :disabled="bezig||koppelOpen||unitOpen||alarmOpen||unitStatusTarget" @change="openBeheer"><option value="" disabled>{{t("Beheer")}}</option><option v-if="gebruiker.KanGebruikersBeheren" value="classes">{{t("Classificaties")}}</option><option v-if="gebruiker.KanGebruikersBeheren" value="pager">DAPNET</option><option v-if="gebruiker.KanGebruikersBeheren" value="database">Database</option><option value="units">{{t("Eenheden")}}</option><option value="users">{{t("Gebruikers")}}</option><option v-if="gebruiker.KanGebruikersBeheren" value="opschaling">{{t("Opschalingsniveau")}}</option><option v-if="gebruiker.KanGebruikersBeheren" value="polygonen">{{t("Polygonen importeren")}}</option><option v-if="gebruiker.KanGebruikersBeheren" value="prioriteiten">{{t("Prioriteiten")}}</option><option v-if="gebruiker.KanGebruikersBeheren" value="status">Status</option><option v-if="gebruiker.KanGebruikersBeheren" value="systeem">{{t("Systeem")}}</option></select><button v-if="systeemBeheer||prioBeheer||statusBeheer||opsBeheer||beheer||classBeheer||unitBeheer||pagerBeheer||polygonenBeheer||databaseBeheer" class="secondary" :disabled="bezig||koppelOpen||unitOpen||alarmOpen||unitStatusTarget" @click="systeemBeheer=false;prioBeheer=false;statusBeheer=false;opsBeheer=false;beheer=false;classBeheer=false;unitBeheer=false;pagerBeheer=false;polygonenBeheer=false;databaseBeheer=false">{{t("Meldkamer")}}</button><button class="secondary" :disabled="bezig||paletteBusy" @click="uitloggen">{{t("Uitloggen")}}</button><button type="button" class="secondary palette-toggle" :disabled="paletteBusy" :title="t(gebruiker.Kleurpalet==='Licht'?'Donker kleurpalet':'Licht kleurpalet')" :aria-label="t(gebruiker.Kleurpalet==='Licht'?'Donker kleurpalet':'Licht kleurpalet')" @click="togglePalette"><svg v-if="gebruiker.Kleurpalet==='Licht'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z"/></svg><svg v-else viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/></svg></button><button type="button" class="secondary palette-toggle" :disabled="audioBusy" :title="t(gebruiker.Audio===1?'Audio uitschakelen':'Audio inschakelen')" :aria-label="t(gebruiker.Audio===1?'Audio uitschakelen':'Audio inschakelen')" :aria-pressed="gebruiker.Audio===1" @click="toggleAudio"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M3 9h4l5-4v14l-5-4H3z"/><path v-if="gebruiker.Audio===1" d="M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/><path v-else d="m16 9 6 6m0-6-6 6"/></svg></button><span v-if="audioError" class="error" role="alert">{{t(audioError)}}</span><span v-if="paletteError" class="error" role="alert">{{t(paletteError)}}</span></div></header>
<main v-if="!authReady"><p>{{t("Even geduld…")}}</p></main>
<main v-else-if="!gebruiker" class="login-page"><section class="panel login-panel"><small>{{appTitle}}</small><h1>{{t("Inloggen")}}</h1><form class="login-form" @submit.prevent="inloggen"><label>{{t("Gebruikersnaam")}}<input v-model="loginNaam" autocomplete="username" required></label><label>{{t("Wachtwoord")}}<input v-model="loginWachtwoord" type="password" autocomplete="current-password" required></label><p v-if="loginFout" class="error" role="alert">{{loginFout}}</p><button :disabled="loginBezig||!loginNaam.trim()||!loginWachtwoord">{{t("Inloggen")}}</button></form></section></main>
<main v-else-if="databaseBeheer && gebruiker.KanGebruikersBeheren" class="database-main"><Databasebeheer :api="api" @reset="databaseReset"/></main>
<main v-else-if="polygonenBeheer && gebruiker.KanGebruikersBeheren"><PolygonenImport :api="api" @imported="polygonenBeheer=false"/></main>
<main v-else-if="pagerBeheer && gebruiker.KanGebruikersBeheren"><Pagerbeheer :api="api"/></main>
<main v-else-if="unitBeheer"><Eenhedenbeheer :api="api" :can-manage="gebruiker.KanGebruikersBeheren"/></main>
<main v-else-if="beheer"><Gebruikersbeheer :api="api" :current="gebruiker.Gebruikersnaam" :can-manage="gebruiker.KanGebruikersBeheren" @changed="refreshUser"/></main>
<main v-else-if="systeemBeheer && gebruiker.KanGebruikersBeheren"><Systeembeheer :api="api" @changed="refreshUser"/></main>
<main v-else-if="prioBeheer && gebruiker.KanGebruikersBeheren"><Prioriteitenbeheer :api="api" @changed="laadPrio"/></main>
<main v-else-if="statusBeheer && gebruiker.KanGebruikersBeheren"><Statusbeheer :api="api" @changed="laadStatus"/></main>
<main v-else-if="opsBeheer && gebruiker.KanGebruikersBeheren"><Opschalingsbeheer :api="api" @changed="laadOps"/></main>
<main v-else-if="classBeheer && gebruiker.KanGebruikersBeheren"><Classificatiebeheer :api="api" @changed="laadClass"/></main>
<main v-else>
<section class="panel"><div class="toolbar"><h2>{{t("Melding bewerken")}}</h2><span class="meta">{{editor.ID ? `#${editor.ID} · ${editor.Datum} · ${editor.Tijd} · ${editor.Status}` : 'Nieuwe melding'}}</span></div><p v-if="fout" role="alert" class="error">{{t(fout)}}</p><p v-if="verbindingsfout" role="alert" class="error">{{t(verbindingsfout)}}</p>
<form class="field-form" @submit.prevent="opslaan"><fieldset :disabled="bezig" class="editor-fields">
<div class="editor-column editor-address">
<label>{{t("Plaats")}}<input v-model="editor.Plaats" @input="clearMap" :disabled="gesloten" maxlength="150"></label>
<label>{{t("Straat en huisnummer")}}<input v-model="editor.StraatHuisnummer" @input="clearMap" :disabled="gesloten" maxlength="250"></label><div class="local-action"><button type="button" class="secondary" :disabled="gesloten||bezig||!online" @click="mapOpen=true">{{t("Kaart")}}</button></div>
<label>{{t("Telefoon")}}<input v-model="editor.Telefoon" :disabled="gesloten" type="tel" maxlength="50"></label>
<label>{{t("Naam")}}<input v-model="editor.Naam" :disabled="gesloten" maxlength="200"></label>
<label>{{t("Postcode")}}<input v-model="editor.Postcode" :disabled="gesloten" maxlength="20"></label><div class="local-action"><button type="button" class="secondary" :disabled="bezig||!online||gesloten||!editor.ID||meldingen.some(m=>m.MasterID===editor.ID)" @click="openKoppel">{{t("Koppel melding")}}</button></div>
</div>
<div class="editor-column editor-status">
<label>{{t("Prioriteit")}}<select v-model="editor.Prioriteit" :disabled="gesloten||!prioriteiten.length"><option :value="null" disabled>{{t("Niet gekozen")}}</option><option v-if="editor.Prioriteit!==null&&!prioriteiten.some(r=>r.Prioriteit===editor.Prioriteit)" :value="editor.Prioriteit">{{editor.Prioriteit}} ({{t("historisch")}})</option><option v-for="r in prioriteiten" :key="r.PrioriteitID" :value="r.Prioriteit">{{r.Prioriteit}}</option></select></label>
<label>{{t("Classificatie")}}<select v-model="editor.Classificatie" :disabled="gesloten"><option value="" disabled>{{t("Niet gekozen")}}</option><option v-for="c in classificaties" :key="c.ID" :value="c.Classificatie">{{c.Classificatie}}</option></select></label>
<label>Status<select v-model="editor.Status" @change="focusLogregel" :disabled="!editor.ID||editor.MasterID!==null||(gesloten&&!kanHeropenen)"><option>Open</option><option value="Gesloten">{{t("Gesloten")}}</option></select></label>
<label>{{t("Opschaling mono")}}<select v-model="editor.OpschalingMono" @change="focusLogregel" :disabled="!editor.ID||gesloten||!opsOpties.mono.length"><option value=""></option><option v-if="editor.OpschalingMono && !opsOpties.mono.some(v=>v.Naam===editor.OpschalingMono)" :value="editor.OpschalingMono" disabled>{{editor.OpschalingMono}} ({{t("historisch")}})</option><option v-for="v in opsOpties.mono" :key="v.ID" :value="v.Naam">{{v.Naam}}</option></select></label>
<label>{{t("Opschaling multi")}}<select v-model="editor.OpschalingMulti" @change="focusLogregel" :disabled="!editor.ID||gesloten||!opsOpties.multi.length"><option value=""></option><option v-if="editor.OpschalingMulti && !opsOpties.multi.some(v=>v.Naam===editor.OpschalingMulti)" :value="editor.OpschalingMulti" disabled>{{editor.OpschalingMulti}} ({{t("historisch")}})</option><option v-for="v in opsOpties.multi" :key="v.ID" :value="v.Naam">{{v.Naam}}</option></select></label>
</div>
<p v-if="editor.MasterID!==null" class="meta full">{{t("Gekoppeld aan hoofdmelding #")}}{{editor.MasterID}}</p>
</fieldset>
<div class="logboek"><label>{{t("Gekoppelde eenheden")}}</label><div class="linked-unit-list"><p v-if="!linkedUnits.length" class="meta">{{t("Geen gekoppelde eenheden.")}}</p><button v-for="u in linkedUnits" :key="u.ID" type="button" class="secondary linked-unit-row" :disabled="bezig||!online||gesloten" @click="openUnitStatus(u)">{{linkedLabel(u)}}</button></div><div class="local-action"><button type="button" class="secondary" :disabled="bezig||!online||gesloten||!editor.ID" @click="openUnits">{{t("Koppel eenheid")}}</button></div><p v-if="unitError&&!unitOpen" class="error">{{t(unitError)}}</p></div>
<div class="logboek"><h3>{{t("Logregels")}}</h3><p v-if="gesloten" class="meta">{{t(kanHeropenen?'Kies Open en sla op om de melding te heropenen.':'Deze melding is gesloten en alleen-lezen.')}}</p><label v-else>{{t("Nieuwe logregel")}}<textarea ref="logveld" @keydown.enter="logEnter" v-model="logtekst" rows="3" maxlength="3000" :disabled="bezig"></textarea></label>
<div class="form-actions"><button type="button" class="secondary" :disabled="bezig" @click="nieuw">{{t("Nieuw")}}</button><button :disabled="!kanOpslaan">{{t("Opslaan")}}</button></div>
</div></form><div class="logboek">
<p v-if="logfout" class="error" role="alert">{{t(logfout)}}</p><p v-if="editor.ID&&!logregels.length" class="meta">{{t("Nog geen logregels.")}}</p>
<article v-for="l in logregels" :key="l.LogID" class="logregel"><small>{{l.Datum.split('-').reverse().join('-')}} · {{l.Tijd}} · Melding #{{l.MeldingID}}</small><p>{{l.Tekst}} <em class="log-author">({{l.Gebruikersnaam || t('Onbekend')}})</em></p></article></div></section>
<section class="panel"><div class="toolbar"><h2>{{t("Meldingen")}}</h2><input :aria-label="t('Zoeken')" v-model="zoek" :placeholder="t('Zoek ID, naam, adres, telefoon…')"></div><nav><button v-for="f in ['Open','Gesloten','Alle']" :key="f" :class="{active:filter===f}" @click="filter=f">{{t(f)}}</button></nav><div class="scroll"><table class="meldingen-table"><thead><tr><th>{{t("Classificatie")}}</th><th>{{t("Eenheden")}}</th><th>{{t("Opschaling mono")}}</th><th>{{t("Opschaling multi")}}</th><th>{{t("Locatie")}}</th><th>{{t("Tijdstempel")}}</th></tr></thead><tbody><tr v-for="m in zichtbaar" :key="m.ID" class="melding-row" :class="{selected:editor.ID===m.ID}" tabindex="0" @click="bewerk(m)" @keydown.enter.self.prevent="bewerk(m)"><td><span class="tag" :class="m.Prioriteit===1?'p1':'p2'">{{m.Prioriteit}}</span> {{m.Classificatie}}</td><td class="melding-eenheden">{{m.EenhedenOverzicht}}</td><td>{{m.OpschalingMono}}</td><td>{{m.OpschalingMulti}}</td><td class="melding-locatie"><div>{{m.StraatHuisnummer}}</div><div>{{m.Plaats}}</div></td><td class="melding-tijdstempel"><div>{{m.Datum.split('-').reverse().join('-')}}</div><div>{{m.Tijd}}</div></td></tr><tr v-if="!zichtbaar.length"><td colspan="6" class="empty">{{t("Geen meldingen gevonden.")}}</td></tr></tbody></table></div></section>

<Locatiepicker v-if="mapOpen" :api="api" :admin="gebruiker.KanGebruikersBeheren" :incident="editor" @cancel="mapOpen=false" @select="useMap"/>
<div v-if="unitStatusTarget" class="modal-backdrop" @keydown.esc="!bezig && (unitStatusTarget=null)"><section class="panel koppel-modal" role="dialog" aria-modal="true" aria-labelledby="unit-status-title"><h2 id="unit-status-title">{{t("Status aanpassen")}}</h2><p>{{linkedLabel(unitStatusTarget)}}</p><label>Status<select v-model="unitStatusValue" :disabled="bezig"><option v-for="s in statusOptions" :key="s.StatusID" :value="s.StatusID">{{s.StatusNummer}} — {{s.StatusNaam}}</option></select></label><p v-if="[4,5].includes(statusNumber(unitStatusValue))&&[1,2].includes(statusNumber(unitStatusTarget.StatusID))" class="meta">{{t("De eenheid wordt ook losgekoppeld van de melding.")}}</p><p v-if="unitStatusError" class="error" role="alert">{{t(unitStatusError)}}</p><div class="form-actions"><button class="secondary" :disabled="bezig" @click="unitStatusTarget=null">{{t("Annuleren")}}</button><button :disabled="bezig||gesloten||unitStatusValue===unitStatusTarget.StatusID" @click="saveUnitStatus">{{t("Opslaan")}}</button></div></section></div><div v-if="unitOpen" class="modal-backdrop" @keydown.esc="!bezig && (unitOpen=false)"><section class="panel koppel-modal unit-modal" role="dialog" aria-modal="true" aria-labelledby="units-title"><h2 id="units-title">{{t("Eenheden koppelen aan melding #")}}{{editor.ID}}</h2><p v-if="unitError" class="error" role="alert">{{t(unitError)}}</p><p v-if="unitLoading" class="meta">{{t("Eenheden laden…")}}</p><div class="unit-transfer"><section v-for="side in [false,true]" :key="String(side)"><h3>{{t(side?'Gekoppelde eenheden':'Beschikbare eenheden')}}</h3><input v-if="!side" type="search" v-model="unitFilter" :aria-label="t('Filter beschikbare eenheden')" :placeholder="t('Filter eenheden…')"><p v-if="!unitLoading&&!unitsForSide(side).length" class="meta">{{t(!side&&unitFilter.trim()?'Geen passende eenheden.':'Geen eenheden.')}}</p><button type="button" class="secondary unit-transfer-item" v-for="u in unitsForSide(side)" :class="!side && u.polygonPriority ? `unit-priority-${u.polygonPriority}` : null" :key="u.ID" :disabled="bezig||unitLoading" @click="moveUnit(u.ID)"><span>{{side?'←':'→'}} {{u.TactischeNaam}}{{u.Omschrijving?.trim()?' ('+u.Omschrijving+')':''}}</span><small>{{u.Locatie || '–'}} — Status {{statusNumber(u.StatusID)}}</small></button></section></div><div class="form-actions"><button class="secondary" :disabled="bezig" @click="unitOpen=false">{{t("Annuleren")}}</button><button :disabled="bezig||gesloten||unitLoading||!unitDirty" @click="linkUnits(false)">{{t("Opslaan")}}</button><button :disabled="bezig||gesloten||unitLoading" @click="linkUnits(true)">{{t("Opslaan en alarmeren")}}</button></div></section></div><div v-if="alarmOpen" class="modal-backdrop" @keydown.esc="!bezig && (alarmOpen=false)"><section class="panel koppel-modal unit-modal" role="dialog" aria-modal="true" aria-labelledby="alarm-title"><h2 id="alarm-title">{{t("Alarmeren – melding #")}}{{editor.ID}}</h2><section class="alarm-section"><div class="unit-transfer"><section><h3>{{t("Gekoppelde eenheden")}}</h3><p v-if="!alarmUnits.length" class="meta">{{t("Geen eenheden.")}}</p><label class="alarm-unit" v-for="u in alarmUnits" :key="u.ID"><input type="checkbox" v-model="alarmIDs" :value="u.ID" :disabled="bezig||unitLoading">{{u.TactischeNaam}}{{u.Omschrijving?' ('+u.Omschrijving+')':''}}</label></section><section><label>{{t("Alarmeringstekst")}}<textarea v-model="alarmTekst" rows="5" :disabled="bezig||unitLoading"></textarea></label></section></div><p v-if="alarmSucces" role="status">{{t(alarmSucces)}}</p><p v-if="alarmFout" class="error" role="alert">{{t(alarmFout)}}</p><div class="form-actions"><button class="secondary" :disabled="bezig" @click="alarmOpen=false">{{t("Sluiten")}}</button><button :disabled="!kanAlarmeren" @click="alarmeren">{{t("Alarmeren")}}</button></div></section></section></div>
<div v-if="koppelOpen" class="modal-backdrop" @keydown.esc="!bezig && (koppelOpen=false)">
<section class="panel koppel-modal" role="dialog" aria-modal="true" aria-labelledby="koppel-titel">
<h2 id="koppel-titel">{{t("Koppel melding #")}}{{editor.ID}}</h2>
<p>{{t("Kies een open hoofdmelding. De actuele melding wordt na bevestiging gesloten.")}}</p>
<p v-if="koppelFout" class="error" role="alert">{{t(koppelFout)}}</p>
<p v-if="!kandidaten.length" class="meta">{{t("Geen beschikbare hoofdmeldingen.")}}</p>
<label>{{t("Hoofdmelding")}}<select v-model="masterKeuze" :disabled="bezig"><option :value="null" disabled>{{t("Kies hoofdmelding")}}</option><option v-for="m in kandidaten" :key="m.ID" :value="m.ID">#{{m.ID}} — {{m.StraatHuisnummer}}, {{m.Plaats}} — {{m.Classificatie}}</option></select></label>
<div class="form-actions"><button class="secondary" :disabled="bezig" @click="koppelOpen=false">{{t("Annuleren")}}</button><button :disabled="bezig||!online||gesloten||!kandidaten.some(m=>m.ID===masterKeuze)" @click="bevestigKoppel">{{t("Koppelen en sluiten")}}</button></div>
</section></div>
</main>
<footer>{{t("CAD · Versie")}} {{appVersion.replace(/\.0$/, '')}} {{t("· LAN systeem · Automatische synchronisatie elke 3 seconden")}}</footer>
</template>
